-- Perguntas da IA (não solicitadas pelo cliente): 44 (mínimo recomendado: 30) | Perguntas do cliente (requisitos): 0

MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_001' AS ID_CONSULTA, 'Quantos eventos de Licitacao Contrato existem no total?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Executiva/Estratégica.' AS OBSERVACOES, 'SELECT COUNT(1) AS QTD_EVENTOS FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_002' AS ID_CONSULTA, 'Como evoluiu o volume mensal de Licitacao Contrato nos últimos 12 meses?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Executiva/Estratégica.' AS OBSERVACOES, 'SELECT TRUNC(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''MM'') AS MES, COUNT(1) AS QTD_EVENTOS FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e WHERE TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'') >= ADD_MONTHS(TRUNC(SYSDATE, ''MM''), -12) GROUP BY TRUNC(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''MM'') ORDER BY MES' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_003' AS ID_CONSULTA, 'Qual a variação percentual do volume de Licitacao Contrato de um mês para o outro?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Executiva/Estratégica.' AS OBSERVACOES, 'WITH m AS (SELECT TRUNC(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''MM'') AS MES, COUNT(1) AS QTD FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e GROUP BY TRUNC(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''MM'')) SELECT MES, QTD, ROUND((QTD - LAG(QTD) OVER (ORDER BY MES)) * 100 / NULLIF(LAG(QTD) OVER (ORDER BY MES), 0), 2) AS PCT_VARIACAO_MES FROM m ORDER BY MES' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_004' AS ID_CONSULTA, 'Como o volume de Licitacao Contrato do ano corrente se compara ao do ano anterior, mês a mês?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Executiva/Estratégica.' AS OBSERVACOES, 'SELECT EXTRACT(MONTH FROM TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'')) AS MES, SUM(CASE WHEN EXTRACT(YEAR FROM TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'')) = EXTRACT(YEAR FROM SYSDATE) THEN 1 ELSE 0 END) AS QTD_ANO_ATUAL, SUM(CASE WHEN EXTRACT(YEAR FROM TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'')) = EXTRACT(YEAR FROM SYSDATE) - 1 THEN 1 ELSE 0 END) AS QTD_ANO_ANTERIOR FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e GROUP BY EXTRACT(MONTH FROM TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'')) ORDER BY MES' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

