MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_024' AS ID_CONSULTA, 'Como Licitacao Contrato se distribuiu por Órgão Publico no último mês completo?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Tática/Operacional.' AS OBSERVACOES, 'SELECT d.SIG_ORGAO, COUNT(1) AS QTD_EVENTOS FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e JOIN DW_GLD.VW_GLD_DIM_ORGAO_PUBLICO_ATUAL d ON d.DIMENSION_KEY = e.DIM_ORGAO_PUBLICO WHERE TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'') >= ADD_MONTHS(TRUNC(SYSDATE, ''MM''), -1) AND TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'') < TRUNC(SYSDATE, ''MM'') GROUP BY d.SIG_ORGAO ORDER BY QTD_EVENTOS DESC' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO, VW_GLD_DIM_ORGAO_PUBLICO_ATUAL' AS OBJETOS_CHAVE FROM DUAL) src
