MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_031' AS ID_CONSULTA, 'Existe sazonalidade em Licitacao Contrato? Qual a média de eventos por mês do ano?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Tática/Operacional.' AS OBSERVACOES, 'SELECT EXTRACT(MONTH FROM TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'')) AS MES_DO_ANO, ROUND(COUNT(1) / NULLIF(COUNT(DISTINCT EXTRACT(YEAR FROM TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''))), 0), 2) AS MEDIA_EVENTOS FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e GROUP BY EXTRACT(MONTH FROM TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'')) ORDER BY MES_DO_ANO' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
