VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_032' AS ID_CONSULTA, 'Em quais dias da semana Licitacao Contrato mais acontece?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Tática/Operacional.' AS OBSERVACOES, 'SELECT TO_CHAR(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''DY'', ''NLS_DATE_LANGUAGE=PORTUGUESE'') AS DIA_SEMANA, COUNT(1) AS QTD_EVENTOS FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e GROUP BY TO_CHAR(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''DY'', ''NLS_DATE_LANGUAGE=PORTUGUESE'') ORDER BY QTD_EVENTOS DESC' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
