MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_033' AS ID_CONSULTA, 'Quais eventos de Licitacao Contrato têm quantidade de itens contrato atípico (acima de 3 desvios-padrão da média)?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Tática/Operacional.' AS OBSERVACOES, 'WITH s AS (SELECT AVG(e.QTD_ITENS_CONTRATO) AS MEDIA, STDDEV(e.QTD_ITENS_CONTRATO) AS DESVIO FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e) SELECT e.DIM_ORGAO_PUBLICO, e.QTD_ITENS_CONTRATO FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e CROSS JOIN s WHERE e.QTD_ITENS_CONTRATO > s.MEDIA + 3 * s.DESVIO ORDER BY e.QTD_ITENS_CONTRATO DESC FETCH FIRST 50 ROWS ONLY' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_034' AS ID_CONSULTA, 'Qual a média móvel de 3 meses de quantidade de itens contrato?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Tática/Operacional.' AS OBSERVACOES, 'WITH m AS (SELECT TRUNC(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''MM'') AS MES, SUM(e.QTD_ITENS_CONTRATO) AS TOTAL FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e GROUP BY TRUNC(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''), ''MM'')) SELECT MES, TOTAL, ROUND(AVG(TOTAL) OVER (ORDER BY MES ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS MEDIA_MOVEL_3M FROM m ORDER BY MES' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
