MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_042' AS ID_CONSULTA, 'Existem eventos de Licitacao Contrato com data no futuro?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Auditoria/Qualidade.' AS OBSERVACOES, 'SELECT COUNT(1) AS QTD_DATA_FUTURA FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e WHERE TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'') > SYSDATE' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
