MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_043' AS ID_CONSULTA, 'Qual a data do evento mais recente de Licitacao Contrato e há quantos dias foi registrado?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Auditoria/Qualidade.' AS OBSERVACOES, 'SELECT MAX(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD'')) AS DATA_MAIS_RECENTE, TRUNC(SYSDATE) - TRUNC(MAX(TO_DATE(TO_CHAR(NULLIF(e.DIM_TEMPO, -1)), ''YYYYMMDD''))) AS DIAS_DESDE_ULTIMO FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO e' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

MERGE INTO DW_GLD.META_CONSULTA_NEGOCIO dst
USING (SELECT 'GLD' AS PROJETO, 'PN_GLD_IA_044' AS ID_CONSULTA, 'O total da view de KPI de Licitacao Contrato confere com a contagem da view de eventos?' AS PERGUNTA_LINGUAGEM_NATURAL, 'PAINEL_GLD' AS PAINEL_RELACIONADO, 'Sugerida pela IA (não solicitada pelo cliente) — horizonte Auditoria/Qualidade.' AS OBSERVACOES, 'SELECT (SELECT SUM(QTD_TOTAL_REGISTROS) FROM DW_GLD.VW_GLD_KPI_LICITACAO_CONTRATO) - (SELECT COUNT(1) FROM DW_GLD.VW_GLD_EVENTO_LICITACAO_CONTRATO) AS DIFERENCA FROM DUAL' AS SQL_VALIDADO_INTERPRETACAO, 'VW_GLD_KPI_LICITACAO_CONTRATO, VW_GLD_EVENTO_LICITACAO_CONTRATO' AS OBJETOS_CHAVE FROM DUAL) src
ON (dst.PROJETO = src.PROJETO AND dst.ID_CONSULTA = src.ID_CONSULTA)
WHEN MATCHED THEN UPDATE SET dst.PERGUNTA_LINGUAGEM_NATURAL = src.PERGUNTA_LINGUAGEM_NATURAL, dst.OBSERVACOES = src.OBSERVACOES, dst.SQL_VALIDADO_INTERPRETACAO = src.SQL_VALIDADO_INTERPRETACAO, dst.OBJETOS_CHAVE = src.OBJETOS_CHAVE, dst.DT_ATUALIZACAO = SYSDATE
WHEN NOT MATCHED THEN INSERT (PROJETO, ID_CONSULTA, PERGUNTA_LINGUAGEM_NATURAL, PAINEL_RELACIONADO, OBSERVACOES, SQL_VALIDADO_INTERPRETACAO, OBJETOS_CHAVE)
VALUES (src.PROJETO, src.ID_CONSULTA, src.PERGUNTA_LINGUAGEM_NATURAL, src.PAINEL_RELACIONADO, src.OBSERVACOES, src.SQL_VALIDADO_INTERPRETACAO, src.OBJETOS_CHAVE);

